INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-7',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"Antibiotic Resistance in Hospitals","passageText":"Every course of antibiotics creates selection pressure. Bacteria that survive treatment reproduce, and their descendants inherit the mechanisms that protected them. Hospitals concentrate this process because they bring together patients with weakened immune systems, invasive devices and frequent prescriptions. A ward that prescribes broad-spectrum drugs for minor infections may see resistant strains spread along the same corridors. Surveillance matters more than any single prescription: laboratories must identify the organism, clinicians must narrow the drug once results arrive, and staff must wash their hands between patients. None of these steps is dramatic, which is precisely why they are easy to neglect. Resistance is not a future problem; it is the cumulative result of present habits.","gapSentence":{"before":"Every course of antibiotics creates selection pressure. Bacteria that survive treatment reproduce, and their descendants inherit the mechanisms that protected them. Hospitals concentrate this process because they bring together patients with weakened immune systems, invasive devices and frequent prescriptions. A ward that prescribes broad-spectrum drugs for minor infections may see resistant strains spread along the same corridors. ","after":" matters more than any single prescription: laboratories must identify the organism, clinicians must narrow the drug once results arrive, and staff must wash their hands between patients. None of these steps is dramatic, which is precisely why they are easy to neglect. Resistance is not a future problem; it is the cumulative result of present habits.","correct":"Surveillance","options":["isolation","Surveillance","treatment","inspection"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["A Guide to Hospital Architecture","Antibiotic Resistance in Hospitals","The Discovery of Penicillin","How Viruses Replicate"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Resistance grows from routine prescribing and hygiene habits, so ordinary discipline matters most.","Resistance is caused only by patients who stop treatment early.","Broad-spectrum antibiotics should be used for every minor infection.","Hospital design has no influence on the spread of bacteria."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Hospitals concentrate this process because they bring together patients with weakened immune systems, invasive devices and frequent prescriptions.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"Surveillance","titleCorrectIndex":1,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"Hospitals concentrate this process because they bring together patients with weakened immune systems, invasive devices and frequent prescriptions."}',
  120,
  true
)
