INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-13',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"Volcanic Ash and Air Travel","passageText":"Volcanic ash is not ordinary dust. Its particles are glassy, abrasive and melt at temperatures reached inside a jet engine, where they can coat turbine blades and stall a compressor. The 2010 eruption in Iceland demonstrated how far the hazard travels: ash drifted across Europe and grounded thousands of flights even though the volcano itself was small by geological standards. Regulators responded with concentration thresholds, allowing aircraft to fly through dilute plumes that were previously avoided entirely. Airlines now combine satellite imagery with engine-wear models to decide where the boundary lies. The result is a compromise between safety and economic cost, revised whenever new evidence arrives.","gapSentence":{"before":"Volcanic ash is not ordinary dust. Its particles are glassy, ","after":" and melt at temperatures reached inside a jet engine, where they can coat turbine blades and stall a compressor. The 2010 eruption in Iceland demonstrated how far the hazard travels: ash drifted across Europe and grounded thousands of flights even though the volcano itself was small by geological standards. Regulators responded with concentration thresholds, allowing aircraft to fly through dilute plumes that were previously avoided entirely. Airlines now combine satellite imagery with engine-wear models to decide where the boundary lies. The result is a compromise between safety and economic cost, revised whenever new evidence arrives.","correct":"abrasive","options":["hollow","transparent","abrasive","smooth"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How Jet Engines Are Manufactured","Weather Forecasting for Sailors","Volcanic Ash and Air Travel","The Geology of Ocean Trenches"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["The 2010 eruption was the largest in recorded history.","Satellite imagery cannot detect ash clouds.","Ash policy balances engine risk against disruption and is continually revised.","Volcanic ash is harmless to modern aircraft."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Its particles are glassy, abrasive and melt at temperatures reached inside a jet engine, where they can coat turbine blades and stall a compressor.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings."]}',
  '{"gapCorrect":"abrasive","titleCorrectIndex":2,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"Its particles are glassy, abrasive and melt at temperatures reached inside a jet engine, where they can coat turbine blades and stall a compressor."}',
  120,
