INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-17',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Language Loss and Documentation","passageText":"A language disappears when parents stop speaking it to their children, not when the last fluent elder dies. The distinction matters for policy. Recording a dictionary preserves vocabulary but does not create new speakers; only daily use in homes, schools and workplaces does. Documentation projects therefore increasingly combine audio archives with community classes and radio programmes. Linguists debate how much grammar must be written down before a language is considered safe, but speakers rarely frame the question that way. For them the priority is whether the language can still be used to raise children, tell jokes and conduct business. A grammar in a university library is a record of loss as often as it is a tool of survival.","gapSentence":{"before":"A language disappears when parents stop speaking it to their children, not when the last ","after":" elder dies. The distinction matters for policy. Recording a dictionary preserves vocabulary but does not create new speakers; only daily use in homes, schools and workplaces does. Documentation projects therefore increasingly combine audio archives with community classes and radio programmes. Linguists debate how much grammar must be written down before a language is considered safe, but speakers rarely frame the question that way. For them the priority is whether the language can still be used to raise children, tell jokes and conduct business. A grammar in a university library is a record of loss as often as it is a tool of survival.","correct":"fluent","options":["fluent","broken","silent","written"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Language Loss and Documentation","The Origins of Indo-European Languages","How Children Acquire Grammar","Translation in International Courts"],"correctIndex":0},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Languages disappear only when their last speaker dies.","Community classes are less useful than printed grammars.","Language survival depends on everyday intergenerational use, not only on archived records.","A complete dictionary guarantees that a language will survive."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A language disappears when parents stop speaking it to their children, not when the last fluent elder dies.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks."]}',
  '{"gapCorrect":"fluent","titleCorrectIndex":0,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"A language disappears when parents stop speaking it to their children, not when the last fluent elder dies."}',
  120,
  true
)
