INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-27',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"The Psychology of Waiting Queues","passageText":"People judge a queue by its perceived duration rather than its measured length. An empty wait feels longer than a busy one, and a wait with visible progress feels shorter than a stationary one. Airports exploit this by placing mirrors near baggage carousels and by reporting which belt will deliver a flight, even when the bags are not yet there. Fairness also matters: a queue that appears to allow jumping generates more complaints than a longer queue that advances evenly. Service designers therefore distract, inform and structure waits rather than simply shortening them. The underlying lesson is that satisfaction is shaped by expectations and by the sense of control, not only by the number of minutes spent standing still.","gapSentence":{"before":"People judge a queue by its ","after":" duration rather than its measured length. An empty wait feels longer than a busy one, and a wait with visible progress feels shorter than a stationary one. Airports exploit this by placing mirrors near baggage carousels and by reporting which belt will deliver a flight, even when the bags are not yet there. Fairness also matters: a queue that appears to allow jumping generates more complaints than a longer queue that advances evenly. Service designers therefore distract, inform and structure waits rather than simply shortening them. The underlying lesson is that satisfaction is shaped by expectations and by the sense of control, not only by the number of minutes spent standing still.","correct":"perceived","options":["measured","imagined","reported","perceived"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Airport Security Since 2001","How Baggage Handling Works","The Economics of Theme Parks","The Psychology of Waiting Queues"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Perceived fairness and progress shape wait satisfaction more than actual duration.","Passengers only care about the physical length of a queue.","Distraction makes waits feel longer in every setting.","Queue design has no effect on customer complaints."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","People judge a queue by its perceived duration rather than its measured length."]}',
  '{"gapCorrect":"perceived","titleCorrectIndex":3,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"People judge a queue by its perceived duration rather than its measured length."}',
  120,
  true
)
