INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-29',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Vertical Farming’s Energy Problem","passageText":"Vertical farms grow crops in stacked trays under artificial light, using a fraction of the land and almost no pesticides. Their advantage is greatest for leafy greens in cities, where transport distances are short and shelf life matters. The weakness is electricity. Sunlight is free, but lamps are not, and the intensity required for fruiting crops makes their energy bill prohibitive. Proponents argue that renewable tariffs and waste heat from nearby buildings can close the gap; critics note that those buildings are not always available and that batteries add further cost. The technology is therefore best understood as a specialised tool for a narrow range of crops rather than a general replacement for fields.","gapSentence":{"before":"Vertical farms grow crops in stacked trays under artificial light, using a fraction of the land and almost no pesticides. Their advantage is greatest for leafy greens in cities, where transport distances are short and shelf life matters. The weakness is electricity. Sunlight is free, but lamps are not, and the intensity required for fruiting crops makes their energy bill ","after":". Proponents argue that renewable tariffs and waste heat from nearby buildings can close the gap; critics note that those buildings are not always available and that batteries add further cost. The technology is therefore best understood as a specialised tool for a narrow range of crops rather than a general replacement for fields.","correct":"prohibitive","options":["moderate","affordable","prohibitive","available"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How LED Lighting Works","Urban Food Markets","Vertical Farming’s Energy Problem","The History of Greenhouse Design"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Artificial lighting is cheaper than sunlight for every crop.","Energy costs are irrelevant to indoor farming.","Vertical farms suit leafy greens but are limited by the cost of artificial light.","Vertical farms can replace all field agriculture immediately."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Sunlight is free, but lamps are not, and the intensity required for fruiting crops makes their energy bill prohibitive.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings."]}',
  '{"gapCorrect":"prohibitive","titleCorrectIndex":2,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"Sunlight is free, but lamps are not, and the intensity required for fruiting crops makes their energy bill prohibitive."}',
  120,
  true
)
