INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-31',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"How Archives Survive Fires","passageText":"Archives burn because paper burns, but the greater loss is often caused by water and smoke rather than flame. A fire in a library triggers sprinklers, and the books that survive the heat absorb water and develop mould within days. Conservators therefore plan for the whole sequence: detection, suppression, freezing and freeze-drying. Digitisation helps, but only for what has already been scanned, and scans rarely capture the material qualities that historians value. The most effective protection is duplication across distant sites, a practice that sounds bureaucratic until a single building is lost. Catastrophe planning is unglamorous work, and that is precisely why it is chronically underfunded.","gapSentence":{"before":"Archives burn because paper burns, but the greater loss is often caused by water and smoke rather than flame. A fire in a library triggers sprinklers, and the books that survive the heat absorb water and develop mould within days. Conservators therefore plan for the whole sequence: detection, ","after":", freezing and freeze-drying. Digitisation helps, but only for what has already been scanned, and scans rarely capture the material qualities that historians value. The most effective protection is duplication across distant sites, a practice that sounds bureaucratic until a single building is lost. Catastrophe planning is unglamorous work, and that is precisely why it is chronically underfunded.","correct":"suppression","options":["recovery","suppression","prevention","detection"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of Papermaking","How Archives Survive Fires","The Invention of the Printing Press","Modern Library Architecture"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Archive survival depends on planning for water, mould and duplication, not only on fire suppression.","Sprinklers always save books without causing damage.","Digitisation fully replaces the need for physical archives.","Fires are the only threat to paper collections."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","A fire in a library triggers sprinklers, and the books that survive the heat absorb water and develop mould within days.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"suppression","titleCorrectIndex":1,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"A fire in a library triggers sprinklers, and the books that survive the heat absorb water and develop mould within days."}',
  120,
  true
)
