INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-33',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"Roman Concrete and the Chemistry of Repair","passageText":"Roman concrete has survived two thousand years of wave action, yet it was not mixed to a modern recipe. Builders used volcanic ash, lime and seawater, and the sea itself helped the material cure. When seawater seeped into cracks, it dissolved minerals that then grew into crystals, sealing the gaps before they widened. Modern concrete often fails at the steel reinforcement, which rusts and expands until the surface breaks away. Engineers studying Roman harbours have begun to design repairs that rely on similar mineral growth. The lesson is not that old buildings were better, but that durability depends on how a material responds to damage rather than on how strong it is when new.","gapSentence":{"before":"Roman concrete has survived two thousand years of wave action, yet it was not mixed to a modern recipe. Builders used volcanic ash, lime and seawater, and the sea itself helped the material cure. When seawater seeped into cracks, it ","after":" minerals that then grew into crystals, sealing the gaps before they widened. Modern concrete often fails at the steel reinforcement, which rusts and expands until the surface breaks away. Engineers studying Roman harbours have begun to design repairs that rely on similar mineral growth. The lesson is not that old buildings were better, but that durability depends on how a material responds to damage rather than on how strong it is when new.","correct":"dissolved","options":["dissolved","absorbed","released","transported"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Roman Concrete and the Chemistry of Repair","The Collapse of Roman Aqueducts","Modern Steel Production","A History of Harbour Walls"],"correctIndex":0},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Modern concrete is stronger than Roman concrete in every way.","Seawater destroys all ancient concrete within decades.","Roman concrete endured because its chemistry allowed damage to seal itself.","Roman builders used steel reinforcement to prevent cracks."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["When seawater seeped into cracks, it dissolved minerals that then grew into crystals, sealing the gaps before they widened.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks."]}',
  '{"gapCorrect":"dissolved","titleCorrectIndex":0,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"When seawater seeped into cracks, it dissolved minerals that then grew into crystals, sealing the gaps before they widened."}',
  120,
  true
)
