INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-35',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Why Handwriting Still Helps Students Think","passageText":"Typing is faster, searchable and easier to edit, so why do some researchers still ask students to write by hand? The answer concerns effort. Forming letters forces the writer to choose words more slowly and to summarise rather than transcribe. In experiments, students who took longhand notes recalled more concepts than those who typed full lectures, even though the typists recorded more sentences. The advantage disappears when handwriting becomes a copying exercise or when the notes are never reviewed. A sensible course therefore mixes both: typing for drafts and archives, handwriting for lectures where selection matters. The tool is less important than the mental work it encourages.","gapSentence":{"before":"Typing is faster, searchable and easier to edit, so why do some researchers still ask students to write by hand? The answer concerns effort. Forming letters forces the writer to choose words more slowly and to summarise rather than ","after":". In experiments, students who took longhand notes recalled more concepts than those who typed full lectures, even though the typists recorded more sentences. The advantage disappears when handwriting becomes a copying exercise or when the notes are never reviewed. A sensible course therefore mixes both: typing for drafts and archives, handwriting for lectures where selection matters. The tool is less important than the mental work it encourages.","correct":"transcribe","options":["translate","delete","repeat","transcribe"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of the Pencil","How to Type Faster","The End of Lecture Notes","Why Handwriting Still Helps Students Think"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Handwriting helps because it slows note-taking enough to require selection.","Typing always produces better learning than handwriting.","Handwriting is useful only for copying texts exactly.","Students should never review their notes."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Forming letters forces the writer to choose words more slowly and to summarise rather than transcribe."]}',
  '{"gapCorrect":"transcribe","titleCorrectIndex":3,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Forming letters forces the writer to choose words more slowly and to summarise rather than transcribe."}',
  120,
  true
)
