INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-37',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"The Hidden Costs of Second-Hand Clothing","passageText":"The second-hand clothing trade is often described as a simple environmental win, but the accounting is more complicated. Reselling a jacket keeps it out of landfill and avoids the materials needed for a new one. Yet the jacket must be collected, sorted, cleaned and shipped, and many garments travel thousands of kilometres before they are worn again. In importing countries, cheap used clothes can undercut local tailors and flood markets with items that are hard to repair. The environmental benefit is therefore real but smaller than the headline figure suggests, and it depends on what happens at the end of the second life. A market that rewards durability would do more than one that rewards volume.","gapSentence":{"before":"The second-hand clothing trade is often described as a simple environmental win, but the ","after":" is more complicated. Reselling a jacket keeps it out of landfill and avoids the materials needed for a new one. Yet the jacket must be collected, sorted, cleaned and shipped, and many garments travel thousands of kilometres before they are worn again. In importing countries, cheap used clothes can undercut local tailors and flood markets with items that are hard to repair. The environmental benefit is therefore real but smaller than the headline figure suggests, and it depends on what happens at the end of the second life. A market that rewards durability would do more than one that rewards volume.","correct":"accounting","options":["storage","design","accounting","marketing"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The End of Fast Fashion","A History of Tailoring","The Hidden Costs of Second-Hand Clothing","How Cotton Is Grown"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Used clothing always strengthens local tailoring industries.","Durability is irrelevant to the clothing trade.","Second-hand clothing helps, but transport and market effects reduce the gain.","Reselling clothes has no environmental benefit at all."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","The second-hand clothing trade is often described as a simple environmental win, but the accounting is more complicated.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings."]}',
  '{"gapCorrect":"accounting","titleCorrectIndex":2,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"The second-hand clothing trade is often described as a simple environmental win, but the accounting is more complicated."}',
  120,
  true
)
