INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-55',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"Coral Restoration as First Aid","passageText":"Coral reefs can recover after bleaching, but only if the conditions that caused the damage improve. Restoration projects therefore begin with water quality and fishing rules rather than with coral. Where the reef is stable, divers attach small fragments grown in nurseries, a method that speeds up growth but cannot create a reef from nothing. Genetic diversity matters: a garden of identical fragments may survive one hot summer and fail the next. Some teams now breed corals that tolerate higher temperatures, though critics warn that this could distract from the harder work of reducing emissions. Restoration is best understood as first aid, not a cure for the warming ocean.","gapSentence":{"before":"Coral reefs can recover after ","after":", but only if the conditions that caused the damage improve. Restoration projects therefore begin with water quality and fishing rules rather than with coral. Where the reef is stable, divers attach small fragments grown in nurseries, a method that speeds up growth but cannot create a reef from nothing. Genetic diversity matters: a garden of identical fragments may survive one hot summer and fail the next. Some teams now breed corals that tolerate higher temperatures, though critics warn that this could distract from the harder work of reducing emissions. Restoration is best understood as first aid, not a cure for the warming ocean.","correct":"bleaching","options":["harvesting","bleaching","flooding","erosion"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Why Oceans Are Becoming Colder","Coral Restoration as First Aid","How Coral Reefs Form","The Economics of Fishing"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Restoration can help damaged reefs but cannot replace action on warming.","Coral gardening can rebuild a reef without healthy water.","Genetic uniformity makes corals more resilient.","Bleaching is caused mainly by fishing nets."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Restoration projects therefore begin with water quality and fishing rules rather than with coral.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"bleaching","titleCorrectIndex":1,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"Restoration projects therefore begin with water quality and fishing rules rather than with coral."}',
  120,
  true
)
