INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-57',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"Building Habits Around Existing Cues","passageText":"Habits are often described as actions that have become automatic, but the useful question is how they start. Research on behaviour change suggests that a new routine is easier to establish when it is attached to an existing cue: after breakfast, before leaving the house, at the end of a meeting. The cue reduces the need to decide, and repetition makes the action feel normal. Rewards matter less than people expect, and grand plans tend to fail because they demand too much at once. Small changes that survive a bad week are more likely to last than ambitious ones that require perfect conditions. The goal is not motivation but a reliable trigger.","gapSentence":{"before":"Habits are often described as actions that have become ","after":", but the useful question is how they start. Research on behaviour change suggests that a new routine is easier to establish when it is attached to an existing cue: after breakfast, before leaving the house, at the end of a meeting. The cue reduces the need to decide, and repetition makes the action feel normal. Rewards matter less than people expect, and grand plans tend to fail because they demand too much at once. Small changes that survive a bad week are more likely to last than ambitious ones that require perfect conditions. The goal is not motivation but a reliable trigger.","correct":"automatic","options":["automatic","painful","public","temporary"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Building Habits Around Existing Cues","The Neuroscience of Willpower","Why Rewards Always Work","How to Break Every Habit in a Week"],"correctIndex":0},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Rewards are the only factor in habit formation.","Habits require constant motivation to continue.","Habits form more reliably from small actions tied to existing cues.","Large ambitious plans are the most reliable way to change behaviour."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Research on behaviour change suggests that a new routine is easier to establish when it is attached to an existing cue: after breakfast, before leaving the house, at the end of a meeting.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks."]}',
  '{"gapCorrect":"automatic","titleCorrectIndex":0,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"Research on behaviour change suggests that a new routine is easier to establish when it is attached to an existing cue: after breakfast, before leaving the house, at the end of a meeting."}',
  120,
  true
)
