INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-59',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Water Mills and Village Power","passageText":"Medieval water mills were not simply machines for grinding grain. They were legal and social arrangements as well. A mill required a weir, a channel and a pond, which changed the flow of the river and could flood a neighbour''s field. Lords who owned the mill often required tenants to use it and to pay a share of the flour, a practice that made milling a source of income as well as a service. Disputes over water rights appear in court records for centuries. The technology was modest, but its organisation shaped village life. Studying the mill therefore means studying property, labour and engineering at the same time.","gapSentence":{"before":"Medieval water mills were not simply machines for grinding grain. They were legal and social arrangements as well. A mill required a ","after":", a channel and a pond, which changed the flow of the river and could flood a neighbour''s field. Lords who owned the mill often required tenants to use it and to pay a share of the flour, a practice that made milling a source of income as well as a service. Disputes over water rights appear in court records for centuries. The technology was modest, but its organisation shaped village life. Studying the mill therefore means studying property, labour and engineering at the same time.","correct":"weir","options":["bridge","road","tower","weir"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Invention of the Windmill","How Flour Is Refined","Medieval Farming Techniques","Water Mills and Village Power"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Water mills were social and legal institutions as well as machines.","Medieval mills had no effect on river flow.","Tenants were never required to use a lord''s mill.","Milling was unrelated to property rights."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","A mill required a weir, a channel and a pond, which changed the flow of the river and could flood a neighbour''s field."]}',
  '{"gapCorrect":"weir","titleCorrectIndex":3,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"A mill required a weir, a channel and a pond, which changed the flow of the river and could flood a neighbour''s field."}',
  120,
  true
)
