INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-69',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"Forecasting Eruptions from Many Signals","passageText":"Predicting an eruption is not a single measurement but a pattern of them. Instruments record small earthquakes, changes in the shape of the ground and the composition of gases escaping from the crater. An increase in sulphur dioxide may suggest that magma is rising, while swelling of the surface indicates that pressure is building. None of these signals is reliable alone, and similar patterns can end without an eruption. Scientists therefore combine data with local knowledge and communicate uncertainty rather than a simple warning. False alarms are costly because they erode trust, yet a missed eruption is worse. Forecasting is a negotiation between evidence, timing and public patience.","gapSentence":{"before":"Predicting an eruption is not a single measurement but a pattern of them. Instruments record small earthquakes, changes in the shape of the ground and the ","after":" of gases escaping from the crater. An increase in sulphur dioxide may suggest that magma is rising, while swelling of the surface indicates that pressure is building. None of these signals is reliable alone, and similar patterns can end without an eruption. Scientists therefore combine data with local knowledge and communicate uncertainty rather than a simple warning. False alarms are costly because they erode trust, yet a missed eruption is worse. Forecasting is a negotiation between evidence, timing and public patience.","correct":"composition","options":["weight","colour","composition","temperature"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How Volcanoes Form Islands","The History of Seismology","Forecasting Eruptions from Many Signals","The Destructive Power of Lava"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["False alarms have no cost for public trust.","Ground swelling always means an eruption is certain.","Eruption forecasts combine several imperfect signals and must convey uncertainty.","A single gas measurement can predict every eruption."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","An increase in sulphur dioxide may suggest that magma is rising, while swelling of the surface indicates that pressure is building.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings."]}',
  '{"gapCorrect":"composition","titleCorrectIndex":2,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"An increase in sulphur dioxide may suggest that magma is rising, while swelling of the surface indicates that pressure is building."}',
  120,
  true
)
