INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-75',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"The Engineering of Spider Silk","passageText":"Spider silk is stronger than steel for its weight, yet a spider produces it at body temperature from water and protein. The thread contains regions that form rigid crystals and regions that remain flexible, and the mixture gives it both strength and stretch. A web can absorb the impact of an insect without breaking because the energy is distributed along the threads and the joints. Engineers have tried to copy the process, but synthetic fibres usually require heat, solvents or both. Producing a material with the same structure at room temperature remains difficult. The spider is therefore an efficient factory, and its advantage lies in the conditions it avoids as much as in the material it makes.","gapSentence":{"before":"Spider silk is stronger than steel for its weight, yet a spider produces it at body temperature from water and protein. The thread contains regions that form ","after":" crystals and regions that remain flexible, and the mixture gives it both strength and stretch. A web can absorb the impact of an insect without breaking because the energy is distributed along the threads and the joints. Engineers have tried to copy the process, but synthetic fibres usually require heat, solvents or both. Producing a material with the same structure at room temperature remains difficult. The spider is therefore an efficient factory, and its advantage lies in the conditions it avoids as much as in the material it makes.","correct":"rigid","options":["hollow","sticky","transparent","rigid"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How Spiders Catch Prey","The Chemistry of Steel","Why Synthetic Fibres Are Stronger","The Engineering of Spider Silk"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Spider silk combines strength and stretch through structure, and is made under mild conditions.","Spider silk is weaker than steel at every scale.","Synthetic fibres already match silk without heat or solvents.","A web breaks because energy is concentrated in one thread."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","The thread contains regions that form rigid crystals and regions that remain flexible, and the mixture gives it both strength and stretch."]}',
  '{"gapCorrect":"rigid","titleCorrectIndex":3,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"The thread contains regions that form rigid crystals and regions that remain flexible, and the mixture gives it both strength and stretch."}',
  120,
  true
)
