INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-79',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"Sign Languages as Spatial Grammar","passageText":"Sign languages are not gestures that accompany spoken language; they are complete languages with their own grammar. One striking feature is how they use space. A signer can place a person or object at a location in front of the body and later refer back to that location, so the space itself carries meaning. Different sign languages do this differently, and a learner cannot simply translate word for word from a spoken language. The visual channel also allows simultaneity: a facial expression can mark a question while the hands describe an action. Studying these structures has changed linguists'' assumptions about what grammar must look like, because it shows that language does not depend on sound.","gapSentence":{"before":"Sign languages are not ","after":" that accompany spoken language; they are complete languages with their own grammar. One striking feature is how they use space. A signer can place a person or object at a location in front of the body and later refer back to that location, so the space itself carries meaning. Different sign languages do this differently, and a learner cannot simply translate word for word from a spoken language. The visual channel also allows simultaneity: a facial expression can mark a question while the hands describe an action. Studying these structures has changed linguists'' assumptions about what grammar must look like, because it shows that language does not depend on sound.","correct":"gestures","options":["pauses","gestures","accents","letters"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Why Gestures Replace Words","Sign Languages as Spatial Grammar","The History of Finger Spelling","How Children Learn to Read"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Sign languages use space and simultaneity as grammatical resources.","Sign languages are gesture systems without grammar.","Sign languages translate spoken words one by one.","All sign languages share a single spatial grammar."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","A signer can place a person or object at a location in front of the body and later refer back to that location, so the space itself carries meaning.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"gestures","titleCorrectIndex":1,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"A signer can place a person or object at a location in front of the body and later refer back to that location, so the space itself carries meaning."}',
  120,
  true
)
