INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-87',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"What Landfills Tell Archaeologists","passageText":"Archaeologists usually study abandoned settlements, but some now dig through modern landfills. The layers record what people bought, threw away and repaired, and the material survives better than many written records. One surprising finding is how much food waste remains identifiable decades later, which challenges assumptions about how quickly organic matter decomposes in a sealed tip. The method has limits: a landfill is not a random sample of a household, and the people who produced the waste may still be alive and able to explain it. Researchers therefore combine excavation with interviews. The approach treats rubbish as evidence, not as a moral judgement about consumption.","gapSentence":{"before":"Archaeologists usually study abandoned ","after":", but some now dig through modern landfills. The layers record what people bought, threw away and repaired, and the material survives better than many written records. One surprising finding is how much food waste remains identifiable decades later, which challenges assumptions about how quickly organic matter decomposes in a sealed tip. The method has limits: a landfill is not a random sample of a household, and the people who produced the waste may still be alive and able to explain it. Researchers therefore combine excavation with interviews. The approach treats rubbish as evidence, not as a moral judgement about consumption.","correct":"settlements","options":["machines","settlements","museums","markets"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Why Recycling Began","What Landfills Tell Archaeologists","The History of Waste Collection","How Soil Is Formed"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Modern landfill archaeology reveals consumption and decomposition, with limits that require other evidence.","Landfills are random samples of household behaviour.","Organic waste disappears completely within a year.","Rubbish is useful only as a moral judgement."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","One surprising finding is how much food waste remains identifiable decades later, which challenges assumptions about how quickly organic matter decomposes in a sealed tip.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"settlements","titleCorrectIndex":1,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"One surprising finding is how much food waste remains identifiable decades later, which challenges assumptions about how quickly organic matter decomposes in a sealed tip."}',
  120,
  true
)
