INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-95',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Antibiotics on the Farm","passageText":"Antibiotics are used in livestock not only to treat illness but also, in some places, to prevent disease in crowded sheds and to promote growth. The practice creates resistant bacteria that can reach people through food, water or direct contact. The link is difficult to measure precisely because many routes exist, but the direction is clear enough for regulators to act. Some countries banned growth promotion decades ago and saw resistance fall; others rely on veterinary prescriptions and better housing. The transition costs money, and farmers with thin margins resist it. A workable policy therefore combines restrictions with support for ventilation, vaccination and smaller stocking densities, because a rule without alternatives is likely to be ignored.","gapSentence":{"before":"Antibiotics are used in livestock not only to treat illness but also, in some places, to prevent disease in crowded sheds and to promote growth. The practice creates ","after":" bacteria that can reach people through food, water or direct contact. The link is difficult to measure precisely because many routes exist, but the direction is clear enough for regulators to act. Some countries banned growth promotion decades ago and saw resistance fall; others rely on veterinary prescriptions and better housing. The transition costs money, and farmers with thin margins resist it. A workable policy therefore combines restrictions with support for ventilation, vaccination and smaller stocking densities, because a rule without alternatives is likely to be ignored.","correct":"resistant","options":["domestic","resistant","friendly","seasonal"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Economics of Dairy Farming","Antibiotics on the Farm","The Discovery of Penicillin","How Meat Is Packaged"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Livestock antibiotic use drives resistance, and restrictions need practical alternatives.","Growth-promoting antibiotics have no link to human health.","Bans always fail without any support for farmers.","Veterinary prescriptions are the only source of resistance."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","The practice creates resistant bacteria that can reach people through food, water or direct contact.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"resistant","titleCorrectIndex":1,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"The practice creates resistant bacteria that can reach people through food, water or direct contact."}',
  120,
  true
)
