INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-97',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"The Physics of Ice Skating","passageText":"Ice skating looks frictionless, but the blade is not simply sliding on a smooth surface. Pressure from the thin edge lowers the melting point of the ice beneath it, creating a thin layer of water that lubricates the glide. Friction also generates heat, which adds to the effect. The blade is curved so that the skater can turn by leaning, and the edges are sharpened at different angles for different manoeuvres. A rink that is too cold feels slow and brittle; one that is too warm becomes soft and tiring. The sport therefore depends on a narrow range of conditions, and the skater is constantly reading the surface through the feet.","gapSentence":{"before":"Ice skating looks frictionless, but the blade is not simply sliding on a smooth surface. Pressure from the thin edge lowers the melting point of the ice beneath it, creating a thin layer of water that ","after":" the glide. Friction also generates heat, which adds to the effect. The blade is curved so that the skater can turn by leaning, and the edges are sharpened at different angles for different manoeuvres. A rink that is too cold feels slow and brittle; one that is too warm becomes soft and tiring. The sport therefore depends on a narrow range of conditions, and the skater is constantly reading the surface through the feet.","correct":"lubricates","options":["lubricates","cools","hardens","colours"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Physics of Ice Skating","The History of Winter Sports","How Ice Rinks Are Built","Why Skates Need Sharpening"],"correctIndex":0},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Warmer ice is always faster for skaters.","Blade shape has no effect on turning.","Ice skating depends on pressure melting, friction and blade geometry.","Skating is frictionless because ice never melts under a blade."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Pressure from the thin edge lowers the melting point of the ice beneath it, creating a thin layer of water that lubricates the glide.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks."]}',
  '{"gapCorrect":"lubricates","titleCorrectIndex":0,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"Pressure from the thin edge lowers the melting point of the ice beneath it, creating a thin layer of water that lubricates the glide."}',
  120,
  true
)
