INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-99',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"Community Land Trusts and Lasting Affordability","passageText":"A community land trust separates the ownership of land from the ownership of the building on it. The trust keeps the land in permanent community ownership and sells or leases the home at a price that excludes speculative gain. Buyers agree to resell to another eligible household at a formula set in advance, so the home stays affordable when the market rises. The model protects public investment, but it also limits what an owner can gain, which makes it unattractive to some buyers. It works best where land is expensive and public subsidy is available. The trust is therefore not a general solution to housing costs, but a way to make a subsidy last longer than one sale.","gapSentence":{"before":"A community land trust separates the ownership of land from the ownership of the building on it. The trust keeps the land in permanent community ownership and sells or leases the home at a price that excludes ","after":" gain. Buyers agree to resell to another eligible household at a formula set in advance, so the home stays affordable when the market rises. The model protects public investment, but it also limits what an owner can gain, which makes it unattractive to some buyers. It works best where land is expensive and public subsidy is available. The trust is therefore not a general solution to housing costs, but a way to make a subsidy last longer than one sale.","correct":"speculative","options":["seasonal","private","foreign","speculative"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of Home Ownership","How Mortgages Are Calculated","Why Rents Always Rise","Community Land Trusts and Lasting Affordability"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Community land trusts preserve affordability by separating land from building ownership.","Community land trusts allow unlimited speculative gain.","The model works equally well in every housing market.","Public subsidy is irrelevant to land trusts."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Buyers agree to resell to another eligible household at a formula set in advance, so the home stays affordable when the market rises."]}',
  '{"gapCorrect":"speculative","titleCorrectIndex":3,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Buyers agree to resell to another eligible household at a formula set in advance, so the home stays affordable when the market rises."}',
