INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-103',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"Why Open-Plan Offices Are Noisy","passageText":"Open-plan offices are designed to encourage conversation, but they often make focused work harder. Sound travels across desks, and speech is especially distracting because the brain automatically processes meaning. Background music or white noise can mask some of it, but the effect depends on the task and the person. Acoustic panels, carpets and soft furniture absorb reflections, while screens and plants break lines of sight. The most effective solution is often organisational: placing teams that talk together near each other and quiet tasks in a separate room. A design that ignores the type of work being done will produce complaints even if the furniture is expensive.","gapSentence":{"before":"Open-plan offices are designed to encourage conversation, but they often make focused work harder. Sound travels across desks, and speech is especially ","after":" because the brain automatically processes meaning. Background music or white noise can mask some of it, but the effect depends on the task and the person. Acoustic panels, carpets and soft furniture absorb reflections, while screens and plants break lines of sight. The most effective solution is often organisational: placing teams that talk together near each other and quiet tasks in a separate room. A design that ignores the type of work being done will produce complaints even if the furniture is expensive.","correct":"distracting","options":["affordable","distracting","relaxing","visible"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Economics of Remote Work","Why Open-Plan Offices Are Noisy","The History of Office Furniture","How to Design a Library"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Open-plan noise is best managed by matching layout to the kind of work being done.","Open-plan offices always improve concentration.","Acoustic panels eliminate all speech distraction.","Expensive furniture guarantees a quiet office."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Sound travels across desks, and speech is especially distracting because the brain automatically processes meaning.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"distracting","titleCorrectIndex":1,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"Sound travels across desks, and speech is especially distracting because the brain automatically processes meaning."}',
  120,
  true
)
