INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-115',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"The Case Against Library Fines","passageText":"Library fines are intended to encourage the return of books, but they can also discourage the people who need the library most. A small charge may be trivial for a wealthy reader and a reason to avoid the building for a family on a tight budget. Many libraries have replaced fines with automatic renewals and reminders, and some report that returns improve because the system is simpler. Others argue that fines protect access for everyone by ensuring that popular items circulate. The evidence is mixed, partly because libraries differ in their users and collections. The debate is a small example of a larger question: whether a public service should punish a minority in order to protect a shared resource.","gapSentence":{"before":"Library fines are intended to encourage the return of books, but they can also discourage the people who need the library most. A small charge may be trivial for a wealthy reader and a reason to avoid the building for a family on a tight budget. Many libraries have replaced fines with automatic ","after":" and reminders, and some report that returns improve because the system is simpler. Others argue that fines protect access for everyone by ensuring that popular items circulate. The evidence is mixed, partly because libraries differ in their users and collections. The debate is a small example of a larger question: whether a public service should punish a minority in order to protect a shared resource.","correct":"renewals","options":["fines","shelves","tickets","renewals"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of Public Libraries","How Books Are Catalogued","Why Reading Is Declining","The Case Against Library Fines"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Library fines may deter needy users, and alternatives can protect access without punishment.","Fines are equally burdensome for every library user.","Automatic renewals always reduce returns.","Fines have no effect on access to popular books."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","A small charge may be trivial for a wealthy reader and a reason to avoid the building for a family on a tight budget."]}',
  '{"gapCorrect":"renewals","titleCorrectIndex":3,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"A small charge may be trivial for a wealthy reader and a reason to avoid the building for a family on a tight budget."}',
  120,
