INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-117',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"Why Fog Is Hard to Forecast","passageText":"Fog is difficult to forecast because it forms in a thin layer near the ground, below the resolution of many weather models. It appears when air cools to its dew point, often overnight, and when tiny particles give water vapour a surface on which to condense. Airports need warnings because visibility affects landing rates and schedules. Forecasters combine sensor readings, satellite images and local knowledge of how valleys and coasts behave. A forecast that is correct for a region can still miss the fog at one runway. The problem is therefore one of scale: the atmosphere is understood in general, but the last hundred metres are where the decisions are made.","gapSentence":{"before":"Fog is difficult to forecast because it forms in a thin layer near the ground, below the resolution of many weather models. It appears when air cools to its dew point, often overnight, and when tiny particles give water vapour a surface on which to ","after":". Airports need warnings because visibility affects landing rates and schedules. Forecasters combine sensor readings, satellite images and local knowledge of how valleys and coasts behave. A forecast that is correct for a region can still miss the fog at one runway. The problem is therefore one of scale: the atmosphere is understood in general, but the last hundred metres are where the decisions are made.","correct":"condense","options":["expand","dissolve","condense","evaporate"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How Clouds Form","The Science of Rainbows","Why Fog Is Hard to Forecast","The History of Aviation"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Visibility has no effect on airport schedules.","Fog can be predicted from temperature alone.","Fog forecasting is limited by the small scale at which fog forms.","Fog forms high in the atmosphere where models are accurate."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","It appears when air cools to its dew point, often overnight, and when tiny particles give water vapour a surface on which to condense.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings."]}',
  '{"gapCorrect":"condense","titleCorrectIndex":2,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"It appears when air cools to its dew point, often overnight, and when tiny particles give water vapour a surface on which to condense."}',
  120,
  true
)
